package delivery_test

import (
	"fmt"
	"os"
	"testing"

	"github.com/stretchr/testify/require"
	"gopkg.in/yaml.v3"

	"github.com/PingCAP-QE/ee-apps/tibuild/pkg/delivery"
)

// goldenDataset is the snapshot generated by hack/image-delivery-golden from
// artifacts/packages/delivery.yaml with the deno generator. It carries the
// rules too, so the test is hermetic (no network, no sibling checkout).
type goldenDataset struct {
	Source     map[string]string               `yaml:"source"`
	Deprecated []string                        `yaml:"deprecated"`
	Rules      map[string][]delivery.ImageRule `yaml:"rules"`
	Cases      []goldenCase                    `yaml:"cases"`
}

type goldenCase struct {
	Source string                `yaml:"source"`
	Tag    string                `yaml:"tag"`
	Plans  []delivery.TargetPlan `yaml:"plans"`
}

func loadGolden(t *testing.T) *goldenDataset {
	t.Helper()
	content, err := os.ReadFile("testdata/image_delivery_golden.yaml")
	require.NoError(t, err)

	var doc goldenDataset
	require.NoError(t, yaml.Unmarshal(content, &doc))
	require.NotEmpty(t, doc.Rules)
	require.NotEmpty(t, doc.Cases)
	return &doc
}

// TestMatchImageMatchesLegacyGenerator expands every recorded case and compares
// it with what the deno generator produced for the same reference. The only
// accepted difference is the `deprecated` list: the legacy generator ignored it,
// the new planner skips those repositories.
func TestMatchImageMatchesLegacyGenerator(t *testing.T) {
	doc := loadGolden(t)
	cfg := &delivery.Config{
		Deprecated:     doc.Deprecated,
		ImageCopyRules: doc.Rules,
	}

	var compared, deprecated int
	for _, tc := range doc.Cases {
		src := fmt.Sprintf("%s:%s", tc.Source, tc.Tag)

		plans, err := cfg.MatchImage(src)
		require.NoError(t, err, src)

		if cfg.IsDeprecated(tc.Source) {
			require.Empty(t, plans, "%s is deprecated and must be skipped", src)
			deprecated++
			continue
		}
		require.Equalf(t, tc.Plans, plans, "plan mismatch for %s", src)
		compared++
	}

	require.Positive(t, compared)
	require.Positive(t, deprecated, "the deprecated list should be exercised")
	t.Logf("compared %d cases, %d deprecated cases skipped", compared, deprecated)
}

// TestGoldenDatasetIsComplete guards the dataset itself: every image_copy_rules
// entry must have at least one recorded expansion, otherwise a rule family could
// silently lose its coverage.
func TestGoldenDatasetIsComplete(t *testing.T) {
	doc := loadGolden(t)

	covered := map[string]int{}
	for _, tc := range doc.Cases {
		if len(tc.Plans) > 0 {
			covered[tc.Source]++
		}
	}
	for repo := range doc.Rules {
		if contains(doc.Deprecated, repo) {
			continue
		}
		require.Positivef(t, covered[repo], "no golden case expands %s", repo)
	}
}

func contains(list []string, want string) bool {
	for _, item := range list {
		if item == want {
			return true
		}
	}
	return false
}
